/**
 * THE FIXTURE SOURCE — this repository's real history, on disk.
 *
 * The archive is not invented. `fixtures/chronicle.json` is generated by
 * `fixtures/generate.mjs` straight out of `git log`: 44 real merges, with
 * their real ticket ids, real commits, real timestamps and real measured
 * footprints. Only the fields git cannot know (cost, review rounds) are
 * synthesised, deterministically from each commit sha.
 *
 * The live dispatches are hand-written to cover every state the village must
 * be able to draw, using today's real branch names. They are a fixture and
 * this module says so out loud in `describe()`.
 *
 * The scripted feed emits REAL SSE event shapes, so the same store code path
 * runs under fixtures and under a live server.
 */

import { gatesFor } from "../state/server-gates.mjs";
import { raceAbort, throwIfAborted } from "../abort.mjs";

const HERE = new URL(".", import.meta.url);

/**
 * Mirror of the real server's `emit`: any record that changes leaves with a
 * gate array that matches it. Without this the fixture emitted stale gates and
 * the village contradicted itself — a parcel beside a stale gate strip.
 */
function refreshed(record) {
  record.gates = gatesFor(record);
  return record;
}

/**
 * Read a fixture in either host. The browser serves them over HTTP; the Node
 * test harness imports this module straight off disk, where `fetch` refuses a
 * `file:` URL. Both paths return the same parsed JSON, so the harness exercises
 * the real source rather than a test double.
 */
async function loadJson(name, { signal } = {}) {
  const message = "Cozy Village fixture load was aborted";
  throwIfAborted(signal, message);
  const url = new URL(`fixtures/${name}`, HERE);
  if (url.protocol === "file:") {
    const { readFile } = await raceAbort(import("node:fs/promises"), signal, message);
    throwIfAborted(signal, message);
    const text = await raceAbort(readFile(url, { encoding: "utf8", signal }), signal, message);
    throwIfAborted(signal, message);
    return JSON.parse(text);
  }
  const response = await raceAbort(fetch(url, { signal }), signal, message);
  throwIfAborted(signal, message);
  if (!response.ok) throw new Error(`fixture ${name} unavailable (${response.status})`);
  const text = await raceAbort(response.text(), signal, message);
  throwIfAborted(signal, message);
  return JSON.parse(text);
}

export function createFixtureSource(options = {}) {
  const handlers = new Set();
  let dispatches = [];
  let loadedChronicle = null;
  const timers = new Map();
  const signal = options.signal;
  /** Ambient scripted events are off unless asked for, so a screenshot holds still. */
  const scripted = options.scripted ?? true;

  const emit = (event) => {
    if (signal?.aborted) return;
    for (const handler of handlers) handler(event);
  };

  const at = (ms, fn, onCancel) => {
    if (signal?.aborted) {
      onCancel?.();
      return undefined;
    }
    let timer;
    timer = setTimeout(() => {
      timers.delete(timer);
      if (!signal?.aborted) fn();
    }, ms);
    timers.set(timer, onCancel);
    return timer;
  };
  const clearTimers = () => {
    for (const [timer, onCancel] of timers) {
      clearTimeout(timer);
      onCancel?.();
    }
    timers.clear();
  };
  const delay = (ms) => new Promise((resolve) => {
    at(ms, () => resolve(true), () => resolve(false));
  });
  signal?.addEventListener?.("abort", clearTimers, { once: true });

  return {
    mode: "fixture",

    async load() {
      const [chronicle, live] = await raceAbort(
        Promise.all([
          loadJson("chronicle.json", { signal }),
          loadJson("dispatches.json", { signal }),
        ]),
        signal,
        "Cozy Village fixture load was aborted",
      );
      throwIfAborted(signal, "Cozy Village fixture load was aborted");
      dispatches = live.dispatches;
      loadedChronicle = chronicle;
      return {
        project: { name: "atelier", requireReview: true },
        projects: [{ name: "atelier", requireReview: true, chronicleRecords: chronicle.records.length }],
        chronicle,
        dispatches,
        convoy: live.convoy,
        board: {
          issues: [
            {
              id: "atelier-village",
              title: "Functional village redesign",
              status: "open",
              priority: 0,
              issue_type: "task",
              dependencies: [],
            },
            {
              id: "atelier-artifacts",
              title: "Boot-frozen artifact projection",
              status: "open",
              priority: 1,
              issue_type: "task",
              dependencies: [{ depends_on_id: "atelier-village", status: "open" }],
            },
          ],
          readyIssues: [
            {
              id: "atelier-village",
              title: "Functional village redesign",
              status: "open",
              priority: 0,
              issue_type: "task",
              dependencies: [],
            },
          ],
          source: ".beads/issues.jsonl fixture",
          tracker: "committed",
          degraded: false,
          generatedAt: chronicle.generatedAt,
        },
        queue: {
          enabled: true,
          unavailable: false,
          consecutiveFailures: 0,
          lastError: null,
          failureLimit: 2,
          parkedTickets: [],
        },
        mainHealth: {
          project: "atelier",
          state: "failed",
          checksTotal: 3,
          unresolvedFailures: [{
            id: "47d48d08",
            dispatchId: "47d48d08",
            commit: "47d48d0",
            acknowledgedAt: null,
            evidenceTail: "browser smoke failed before the fixture snapshot",
          }],
          running: [],
        },
        artifacts: {
          project: "atelier",
          generatedAt: chronicle.generatedAt,
          artifacts: [
            {
              kind: "spec",
              title: "Cozy Village world-model redesign",
              path: "docs/specs/atelier-spec-village-redesign.md",
              updatedAt: chronicle.generatedAt,
            },
            {
              kind: "spec",
              title: "Cozy Village live fixes",
              path: "docs/specs/atelier-spec-village-live-fixes.md",
              updatedAt: chronicle.generatedAt,
            },
            {
              kind: "design",
              title: "World contract v0",
              path: "docs/design/world-contract-v0.md",
              updatedAt: chronicle.generatedAt,
            },
            {
              kind: "design",
              title: "Cozy Village manifesto",
              path: "docs/design/directions/E-cozy-village/manifesto.md",
              updatedAt: chronicle.generatedAt,
            },
          ],
        },
      };
    },

    subscribe(handler) {
      handlers.add(handler);
      if (!scripted) return () => handlers.delete(handler);

      /* Every scripted beat addresses a dispatch by id. If an id drifts out of
         the fixture, the beat must FAIL LOUDLY rather than quietly not fire -
         a demo that has silently stopped being alive is the worst possible
         failure mode for this theme. */
      const find = (id) => {
        const record = dispatches.find((r) => r.id === id);
        if (!record) {
          console.error(`[cozy-village] scripted arc references a dispatch that does not exist: ${id}`);
        }
        return record;
      };

      /* A short scripted arc, so the village can be seen being alive without
         a server. Every event below is a real Atelier event shape.

         Note what is NOT here: no event moves a parcel except by changing
         authoritative lifecycle state. Usage ticks create a brief labelled
         activity and leave the parcel at its current station. */

      // 12s: Juniper's verify settles, moving the parcel to its next real bay.
      at(12_000, () => {
        const record = find("a15c9d77");
        if (!record) return;
        record.verify = {
          state: "passed",
          attempt: 1,
          steps: [{ command: "node --test server/**/*.test.mjs", exitCode: 0, durationMs: 47210, tail: "# pass 1184" }],
          attempts: [{ state: "passed", attempt: 1, steps: [] }],
          testedTree: "5aa20c31",
          mainBranch: "main",
          commitsBehind: 0,
        };
        record.outcome = { kind: "completed", changes: "changed", question: null, finalMessage: "retrieved" };
        record.state = "completed";
        record.diff = { insertions: 168, deletions: 24, files: 5 };
        emit({ type: "status", dispatchId: record.id, seq: 41, state: "completed", record: { ...refreshed(record) } });
      });

      // 5s and 19s: spend ticks. Presence, never progress.
      at(5_000, () =>
        emit({ type: "usage", dispatchId: find("a15c9d77")?.id, seq: 38, turns: 21, costUSD: 2.63, inputTokens: 411_002, outputTokens: 18_440 }),
      );
      at(19_000, () =>
        emit({ type: "usage", dispatchId: find("d904ce38")?.id, seq: 77, turns: 55, costUSD: 9.41, inputTokens: 902_551, outputTokens: 40_118 }),
      );

      // 26s: Marisol's second review round flips to pass.
      at(26_000, () => {
        const record = find("d904ce38");
        if (!record) return;
        const round = {
          dispatchId: "0ab3f951",
          round: 2,
          at: new Date().toISOString(),
          reviewedHead: "d1e88a70",
          verdict: "pass",
          findingCount: 0,
          summary:
            "Round two clears all three blockers. The drain cursor survives a restart, the spend readout agrees with the drain it explains, and the log tap is total. Re-read the fencing path I flagged; it is correct.",
        };
        const rounds = [...(record.review?.rounds ?? []).slice(0, 1), round];
        record.review = { ...round, current: round, rounds };
        emit({
          type: "review",
          dispatchId: record.id,
          seq: 79,
          reviewDispatchId: round.dispatchId,
          reviewedHead: round.reviewedHead,
          branchHead: record.branchHead,
          round: 2,
          at: round.at,
          verdict: "pass",
          summary: round.summary,
          findingCount: 0,
          record: { ...refreshed(record) },
        });
      });

      // 38s: a new dispatch arrives at a workshop bench.
      at(38_000, () => {
        const record = {
          id: "c8d20f13",
          project: "atelier",
          ticketId: "atelier-kg5",
          title: "main-health no-data fix - zero-check main is not a pass",
          branch: "atelier-arch/main-health-no-data",
          branchHead: null,
          lane: "claude",
          model: "haiku",
          state: "running",
          startedAt: new Date().toISOString(),
          costUSD: 0,
          turns: 0,
          outcome: null,
          verify: null,
          review: null,
          merged: null,
          dismissed: null,
          postMerge: null,
          orphanUnresolved: false,
          strandedBrWrites: false,
          diff: null,
        };
        dispatches.push(refreshed(record));
        emit({ type: "status", dispatchId: record.id, seq: 1, state: "running", record: { ...record } });
      });

      return () => {
        const failures = [];
        try {
          handlers.delete(handler);
        } catch (error) {
          failures.push({ step: "fixture.handlers", error });
        }
        try {
          clearTimers();
        } catch (error) {
          failures.push({ step: "fixture.timers", error });
        }
        if (failures.length > 0) {
          const error = new AggregateError(
            failures.map((failure) => failure.error),
            "Cozy Village fixture source cleanup failed",
          );
          error.name = "CozyVillageSourceCleanupError";
          error.failures = failures;
          throw error;
        }
      };
    },

    /**
     * A fixture merge runs the REAL sequence: the record gains `merged`, then
     * a `status` event carries `detail: "merged <sha7>"` - which is exactly
     * how a merge reaches a client from a live server (there is no `merge`
     * event type). The celebration therefore fires on the same code path.
     */
    async merge(id) {
      const record = dispatches.find((r) => r.id === id);
      if (!record) throw Object.assign(new Error(`Unknown dispatch: ${id}`), { status: 404 });
      const commit = `${Math.floor(Math.random() * 0xfffffff).toString(16).padStart(7, "0")}`;
      record.merged = { commit, mergedAt: new Date().toISOString(), strategy: "primary-merge" };
      record.state = "completed";
      record.postMerge = { state: "queued", commit, steps: [], queuedAt: record.merged.mergedAt };
      if (!await delay(260)) return record;
      emit({
        type: "status",
        dispatchId: id,
        seq: 99,
        state: "completed",
        detail: `merged ${commit}`,
        record: { ...refreshed(record) },
      });
      return record;
    },

    async dismiss(id) {
      const record = dispatches.find((r) => r.id === id);
      if (!record) throw Object.assign(new Error(`Unknown dispatch: ${id}`), { status: 404 });
      record.dismissed = { at: new Date().toISOString() };
      emit({ type: "status", dispatchId: id, seq: 98, state: record.state, record: { ...refreshed(record) } });
      return record;
    },

    async reply(id, text) {
      const record = dispatches.find((r) => r.id === id);
      if (!record) throw Object.assign(new Error(`Unknown dispatch: ${id}`), { status: 404 });
      record.state = "resuming";
      record.outcome = { ...record.outcome, question: null };
      emit({ type: "reply", dispatchId: id, seq: 30, text });
      emit({ type: "status", dispatchId: id, seq: 31, state: "resuming", record: { ...record } });
      return record;
    },

    async ackMainHealth() {
      // Acknowledging dims the clocktower lamp. It does NOT take the scaffold
      // down - only a later passing merge commit resolves a post-merge failure.
      throw Object.assign(
        new Error("Acknowledging main health needs a live server; the fixture dock keeps its scaffold."),
        { status: 501 },
      );
    },

    dashboardHref: (id) => `#dispatch/${encodeURIComponent(id)}`,

    describe() {
      /* COUNT WHAT WAS LOADED, never a number typed into a string. The
         hardcoded "44" was already stale — the generator now ships 45 — and a
         provenance line that misreports its own data is the exact failure this
         theme exists to refuse. It is derived, so it cannot drift again. */
      if (!loadedChronicle) {
        /* Asked before load() resolved. "0 merges read from git" would be a
           measurement this source has not taken — say so instead. */
        return {
          mode: "fixture",
          label: "Fixture — measured archive, scripted present",
          detail: "not loaded yet",
        };
      }
      const merges = loadedChronicle.records?.length ?? 0;
      const measured = loadedChronicle.records?.some((r) => r?.diff) ?? false;
      return {
        mode: "fixture",
        label: "Fixture — measured archive, scripted present",
        detail:
          `${merges} merges read from git (ids, tickets, commits and timestamps are measured` +
          `${measured ? ", and so are diff footprints" : ""}). ` +
          `${dispatches.length} live dispatches are hand-written to cover the station grammar. ` +
          "Every record carries the server's own gatesFor projection.",
      };
    },
  };
}
